using System;
using System.Collections.Generic;
using UnityEngine;
using Framework.Grid;
using Game.Map;

namespace Game.Stage
{
    /// <summary>
    /// ステージ内のキャラクターや配置物の
    /// GameObject生成と消去を管理するクラス。
    ///
    /// ステージの進行管理やキャラクター制御は行わない。
    /// </summary>
    [DisallowMultipleComponent]
    public class MazeStageSpawner : MonoBehaviour
    {
        #region Inspector Fields

        [Header("生成Prefab設定")]

        /// <summary>
        /// プレイヤーのPrefab。
        /// </summary>
        [SerializeField]
        private GameObject playerPrefab;

        /// <summary>
        /// 敵のPrefab。
        /// </summary>
        [SerializeField]
        private GameObject enemyPrefab;

        /// <summary>
        /// 宝石のPrefab。
        /// </summary>
        [SerializeField]
        private GameObject gemPrefab;

        /// <summary>
        /// アイテムのPrefab。
        /// </summary>
        [SerializeField]
        private GameObject itemPrefab;

        [Header("生成先設定")]

        /// <summary>
        /// 生成オブジェクトの親Transform。
        /// 未設定の場合は自身のTransformを使用する。
        /// </summary>
        [SerializeField]
        private Transform spawnParent;

        [Header("描画位置設定")]

        /// <summary>
        /// キャラクターのZ座標補正値。
        /// </summary>
        [SerializeField]
        private float characterZOffset = -0.2f;

        /// <summary>
        /// 宝石やアイテムのZ座標補正値。
        /// </summary>
        [SerializeField]
        private float collectibleZOffset = -0.1f;

        #endregion

        #region Runtime Fields

        /// <summary>
        /// 現在監視しているマップ。
        /// </summary>
        private GridMap<MazeCell> map;

        /// <summary>
        /// 現在使用している座標変換システム。
        /// </summary>
        private GridCoordinateConverter coordinateConverter;

        /// <summary>
        /// 現在生成されているプレイヤー。
        /// </summary>
        private GameObject playerInstance;

        /// <summary>
        /// 現在生成されている敵の一覧。
        /// </summary>
        private readonly List<GameObject> enemyInstances =
            new List<GameObject>();

        /// <summary>
        /// 宝石の座標とGameObjectの対応表。
        /// </summary>
        private readonly Dictionary<Vector2Int, GameObject>
            gemInstances =
                new Dictionary<Vector2Int, GameObject>();

        /// <summary>
        /// アイテムの座標とGameObjectの対応表。
        /// </summary>
        private readonly Dictionary<Vector2Int, GameObject>
            itemInstances =
                new Dictionary<Vector2Int, GameObject>();

        #endregion

        #region Properties

        /// <summary>
        /// 生成済みのプレイヤー。
        /// </summary>
        public GameObject PlayerInstance =>
            playerInstance;

        /// <summary>
        /// 生成済みの敵一覧。
        /// </summary>
        public IReadOnlyList<GameObject> EnemyInstances =>
            enemyInstances.AsReadOnly();

        /// <summary>
        /// 現在生成されている宝石の数。
        /// </summary>
        public int GemInstanceCount =>
            gemInstances.Count;

        /// <summary>
        /// 現在生成されているアイテムの数。
        /// </summary>
        public int ItemInstanceCount =>
            itemInstances.Count;

        #endregion

        #region Unity Methods

        /// <summary>
        /// オブジェクト破棄時の後処理。
        /// </summary>
        private void OnDestroy()
        {
            ClearStage();
        }

        #endregion

        #region Public Methods

        /// <summary>
        /// ステージ生成結果に基づいて
        /// キャラクターと配置物を生成する。
        /// </summary>
        /// <param name="result">ステージ生成結果</param>
        /// <param name="converter">座標変換システム</param>
        public void SpawnStage(
            MazeStageGenerationResult result,
            GridCoordinateConverter converter)
        {
            if (result == null)
            {
                throw new ArgumentNullException(
                    nameof(result));
            }

            if (converter == null)
            {
                throw new ArgumentNullException(
                    nameof(converter));
            }

            // 以前のステージの生成物を消去する。
            ClearStage();

            map = result.Map;
            coordinateConverter = converter;

            // プレイヤーを生成する。
            playerInstance = SpawnObject(
                playerPrefab,
                result.PlayerSpawnPosition,
                characterZOffset,
                "Player");

            // 敵を生成する。
            for (int i = 0;
                 i < result.EnemySpawnPositions.Count;
                 i++)
            {
                GameObject enemy = SpawnObject(
                    enemyPrefab,
                    result.EnemySpawnPositions[i],
                    characterZOffset,
                    $"Enemy_{i + 1}");

                if (enemy != null)
                {
                    enemyInstances.Add(enemy);
                }
            }

            // マップ全体から宝石とアイテムを生成する。
            foreach (Vector2Int position in map.GetPositions())
            {
                MazeCell cell = map.GetCell(position);

                if (cell.HasGem)
                {
                    SpawnGem(position);
                }

                if (cell.HasItem)
                {
                    SpawnItem(position);
                }
            }

            // マップ変更時に生成物を同期する。
            map.CellChanged += OnCellChanged;
        }

        /// <summary>
        /// 現在のステージで生成した
        /// すべてのGameObjectを消去する。
        /// </summary>
        public void ClearStage()
        {
            if (map != null)
            {
                map.CellChanged -= OnCellChanged;
            }

            DestroyObject(playerInstance);
            playerInstance = null;

            foreach (GameObject enemy in enemyInstances)
            {
                DestroyObject(enemy);
            }

            enemyInstances.Clear();

            foreach (GameObject gem in gemInstances.Values)
            {
                DestroyObject(gem);
            }

            gemInstances.Clear();

            foreach (GameObject item in itemInstances.Values)
            {
                DestroyObject(item);
            }

            itemInstances.Clear();

            map = null;
            coordinateConverter = null;
        }

        #endregion

        #region Spawn Methods

        /// <summary>
        /// 指定された座標にPrefabを生成する。
        /// </summary>
        /// <param name="prefab">生成対象Prefab</param>
        /// <param name="position">グリッド座標</param>
        /// <param name="zOffset">Z座標補正値</param>
        /// <param name="objectName">生成後の名前</param>
        /// <returns>生成されたGameObject</returns>
        private GameObject SpawnObject(
            GameObject prefab,
            Vector2Int position,
            float zOffset,
            string objectName)
        {
            // Prefab未設定の場合は生成を省略する。
            if (prefab == null)
            {
                return null;
            }

            Vector3 worldPosition =
                coordinateConverter.GetCellCenterWorld(
                    position);

            worldPosition.z += zOffset;

            Transform parent = spawnParent != null
                ? spawnParent
                : transform;

            GameObject instance = Instantiate(
                prefab,
                worldPosition,
                Quaternion.identity,
                parent);

            instance.name = objectName;

            return instance;
        }

        /// <summary>
        /// 指定座標に宝石を生成する。
        /// </summary>
        /// <param name="position">生成座標</param>
        private void SpawnGem(Vector2Int position)
        {
            if (gemInstances.ContainsKey(position))
            {
                return;
            }

            GameObject instance = SpawnObject(
                gemPrefab,
                position,
                collectibleZOffset,
                $"Gem_{position.x}_{position.y}");

            if (instance != null)
            {
                gemInstances.Add(position, instance);
            }
        }

        /// <summary>
        /// 指定座標にアイテムを生成する。
        /// </summary>
        /// <param name="position">生成座標</param>
        private void SpawnItem(Vector2Int position)
        {
            if (itemInstances.ContainsKey(position))
            {
                return;
            }

            GameObject instance = SpawnObject(
                itemPrefab,
                position,
                collectibleZOffset,
                $"Item_{position.x}_{position.y}");

            if (instance != null)
            {
                itemInstances.Add(position, instance);
            }
        }

        #endregion

        #region Remove Methods

        /// <summary>
        /// 指定座標の生成物を消去する。
        /// </summary>
        /// <param name="instances">生成物の対応表</param>
        /// <param name="position">消去対象座標</param>
        private void RemoveObject(
            Dictionary<Vector2Int, GameObject> instances,
            Vector2Int position)
        {
            if (!instances.TryGetValue(
                position,
                out GameObject instance))
            {
                return;
            }

            instances.Remove(position);

            DestroyObject(instance);
        }

        /// <summary>
        /// 指定されたGameObjectを無効化して破棄する。
        /// </summary>
        /// <param name="instance">破棄対象</param>
        private void DestroyObject(GameObject instance)
        {
            if (instance == null)
            {
                return;
            }

            // Destroyはフレーム終了時に実行されるため、
            // 先に無効化して表示や判定の重複を防ぐ。
            instance.SetActive(false);

            Destroy(instance);
        }

        #endregion

        #region Event Methods

        /// <summary>
        /// マップデータの変更に応じて
        /// 宝石やアイテムのGameObjectを同期する。
        /// </summary>
        /// <param name="position">変更された座標</param>
        /// <param name="previousCell">変更前のデータ</param>
        /// <param name="newCell">変更後のデータ</param>
        private void OnCellChanged(
            Vector2Int position,
            MazeCell previousCell,
            MazeCell newCell)
        {
            // 宝石の有無が変化した場合。
            if (previousCell.HasGem != newCell.HasGem)
            {
                if (newCell.HasGem)
                {
                    SpawnGem(position);
                }
                else
                {
                    RemoveObject(
                        gemInstances,
                        position);
                }
            }

            // アイテムの有無が変化した場合。
            if (previousCell.HasItem != newCell.HasItem)
            {
                if (newCell.HasItem)
                {
                    SpawnItem(position);
                }
                else
                {
                    RemoveObject(
                        itemInstances,
                        position);
                }
            }
        }

        #endregion
    }
}
